import time

from .models import ClickEvent, ShortLink
from .shortcode import candidate_codes


class CollisionExhaustedError(RuntimeError):
    pass


class LinkRepository:
    def __init__(self, db, code_length=7):
        self.db = db
        self.code_length = code_length

    def _row_to_link(self, row):
        if row is None:
            return None
        return ShortLink(code=row["code"], url=row["url"], created_at=row["created_at"])

    def find_by_code(self, code):
        row = self.db.execute("SELECT * FROM links WHERE code = ?", (code,)).fetchone()
        return self._row_to_link(row)

    def get_or_create(self, url):
        """Deterministically derive a short code from the URL's content hash.

        Walking the candidate sequence in order and checking the DB each
        time makes this idempotent: shortening the same URL twice always
        returns the same code, and a hash collision with a *different*
        URL is resolved by deterministically advancing to the next salted
        candidate rather than retrying with fresh randomness.
        """
        for code, _salt in candidate_codes(url, length=self.code_length):
            existing = self.find_by_code(code)
            if existing is None:
                created_at = time.time()
                self.db.execute(
                    "INSERT INTO links (code, url, created_at) VALUES (?, ?, ?)",
                    (code, url, created_at),
                )
                self.db.commit()
                return ShortLink(code=code, url=url, created_at=created_at), True
            if existing.url == url:
                return existing, False
        raise CollisionExhaustedError(f"Could not derive a unique code for {url!r}")

    def delete(self, code):
        cur = self.db.execute("DELETE FROM links WHERE code = ?", (code,))
        self.db.commit()
        return cur.rowcount > 0


class ClickRepository:
    def __init__(self, db):
        self.db = db

    def record(self, code, referrer=None, ip=None, ts=None):
        ts = time.time() if ts is None else ts
        self.db.execute(
            "INSERT INTO click_events (code, ts, referrer, ip) VALUES (?, ?, ?, ?)",
            (code, ts, referrer, ip),
        )
        self.db.commit()

    def count_for(self, code):
        row = self.db.execute(
            "SELECT COUNT(*) AS n FROM click_events WHERE code = ?", (code,)
        ).fetchone()
        return row["n"]

    def list_for(self, code, limit=100):
        rows = self.db.execute(
            "SELECT * FROM click_events WHERE code = ? ORDER BY ts DESC LIMIT ?",
            (code, limit),
        ).fetchall()
        return [
            ClickEvent(id=r["id"], code=r["code"], ts=r["ts"], referrer=r["referrer"], ip=r["ip"])
            for r in rows
        ]

    def last_click(self, code):
        row = self.db.execute(
            "SELECT MAX(ts) AS last_ts FROM click_events WHERE code = ?", (code,)
        ).fetchone()
        return row["last_ts"]

from urllib.parse import urlparse

from flask import Blueprint, current_app, jsonify, redirect, request

from .analytics import build_summary
from .db import get_db
from .ratelimit import rate_limited
from .repository import ClickRepository, LinkRepository

bp = Blueprint("shortener", __name__)


def _repos():
    db = get_db()
    code_length = current_app.config["CODE_LENGTH"]
    return LinkRepository(db, code_length=code_length), ClickRepository(db)


def _is_valid_url(url):
    if not isinstance(url, str) or len(url) > 4096:
        return False
    parsed = urlparse(url)
    return parsed.scheme in ("http", "https") and bool(parsed.netloc)


@bp.post("/api/shorten")
@rate_limited("shorten")
def shorten():
    payload = request.get_json(silent=True) or {}
    url = payload.get("url")

    if not _is_valid_url(url):
        return jsonify({"error": "url must be a valid http(s) URL"}), 400

    link_repo, _ = _repos()
    link, created = link_repo.get_or_create(url)
    status = 201 if created else 200
    return jsonify(link.to_dict(current_app.config["BASE_URL"])), status


@bp.get("/api/links/<code>")
@rate_limited("read")
def get_link(code):
    link_repo, click_repo = _repos()
    link = link_repo.find_by_code(code)
    if link is None:
        return jsonify({"error": "not found"}), 404
    data = link.to_dict(current_app.config["BASE_URL"])
    data["clicks"] = click_repo.count_for(code)
    return jsonify(data)


@bp.get("/api/links/<code>/analytics")
@rate_limited("read")
def get_analytics(code):
    link_repo, click_repo = _repos()
    link = link_repo.find_by_code(code)
    if link is None:
        return jsonify({"error": "not found"}), 404
    return jsonify(build_summary(link, click_repo))


@bp.delete("/api/links/<code>")
@rate_limited("write")
def delete_link(code):
    link_repo, _ = _repos()
    deleted = link_repo.delete(code)
    if not deleted:
        return jsonify({"error": "not found"}), 404
    return "", 204


@bp.get("/<code>")
@rate_limited("redirect")
def follow(code):
    link_repo, click_repo = _repos()
    link = link_repo.find_by_code(code)
    if link is None:
        return jsonify({"error": "not found"}), 404

    click_repo.record(
        code,
        referrer=request.headers.get("Referer"),
        ip=request.headers.get("X-Forwarded-For", request.remote_addr),
    )
    return redirect(link.url, code=302)

